import * as fs from 'node:fs';

const decoder = new TextDecoder();
const encoder = new TextEncoder();

function errorDetails(error) {
  return {
    name: error?.name ?? 'Error',
    code: error?.code ?? null,
    message: error?.message ?? String(error),
  };
}

function json(body, status = 200) {
  return Response.json(body, { status });
}

function bundleEvidence() {
  const entries = fs.readdirSync('/bundle');
  let writeError = null;
  try {
    fs.writeFileSync('/bundle/evidence-write.txt', 'forbidden');
  } catch (error) {
    writeError = errorDetails(error);
  }
  return {
    outcome: Array.isArray(entries) && writeError !== null ? 'pass' : 'fail',
    readable: Array.isArray(entries),
    entries,
    immutable: writeError !== null,
    writeError,
  };
}

function tmpEvidence() {
  const path = '/tmp/workerd-vfs-evidence.txt';
  const previousExists = fs.existsSync(path);
  fs.writeFileSync(path, 'tmp-read-write-ok');
  const body = decoder.decode(fs.readFileSync(path));
  return {
    outcome: !previousExists && body === 'tmp-read-write-ok' ? 'pass' : 'fail',
    previousExists,
    body,
  };
}

function devNullEvidence() {
  const descriptor = fs.openSync('/dev/null', 'r+');
  try {
    const written = fs.writeSync(descriptor, encoder.encode('discard-me'));
    const target = new Uint8Array(16);
    const read = fs.readSync(descriptor, target, 0, target.byteLength, null);
    return {
      outcome: written === 10 && read === 0 ? 'pass' : 'fail',
      written,
      read,
    };
  } finally {
    fs.closeSync(descriptor);
  }
}

function devZeroEvidence() {
  const descriptor = fs.openSync('/dev/zero', 'r');
  try {
    const target = new Uint8Array(32);
    const read = fs.readSync(descriptor, target, 0, target.byteLength, null);
    const allZero = target.every((value) => value === 0);
    return {
      outcome: read === target.byteLength && allZero ? 'pass' : 'fail',
      read,
      allZero,
    };
  } finally {
    fs.closeSync(descriptor);
  }
}

function devRandomEvidence() {
  const descriptor = fs.openSync('/dev/random', 'r');
  try {
    const first = new Uint8Array(32);
    const second = new Uint8Array(32);
    const firstRead = fs.readSync(descriptor, first, 0, first.byteLength, null);
    const secondRead = fs.readSync(descriptor, second, 0, second.byteLength, null);
    const firstNonZero = first.some((value) => value !== 0);
    const secondNonZero = second.some((value) => value !== 0);
    const distinct = first.some((value, index) => value !== second[index]);
    return {
      outcome: firstRead === 32 && secondRead === 32 && firstNonZero && secondNonZero && distinct ? 'pass' : 'fail',
      firstRead,
      secondRead,
      firstNonZero,
      secondNonZero,
      distinct,
    };
  } finally {
    fs.closeSync(descriptor);
  }
}

function storageEvidence(path) {
  if (path === '/storage-allowed-read') {
    const body = fs.readFileSync('/storage/readonly/message.txt', 'utf8');
    if (body === 'fixture-read-ok\n') return { outcome: 'allowed-read' };
  }
  if (path === '/storage-ro-write-denied') {
    try {
      fs.writeFileSync('/storage/readonly/denied.txt', 'forbidden');
    } catch (error) {
      if (error?.code === 'EROFS') return { outcome: 'ro-write-denied' };
      throw error;
    }
  }
  if (path === '/storage-rw-write') {
    fs.writeFileSync('/storage/scratch/allowed.txt', 'rw-ok');
    if (fs.readFileSync('/storage/scratch/allowed.txt', 'utf8') === 'rw-ok') {
      return { outcome: 'rw-write' };
    }
  }
  if (path === '/storage-traversal-denied') {
    try {
      fs.readFileSync('/storage/readonly/escape/secret.txt');
    } catch {
      return { outcome: 'traversal-denied' };
    }
  }
  if (path === '/storage-unlisted-denied') {
    try {
      fs.readFileSync('/storage/unlisted/secret.txt');
    } catch (error) {
      if (error?.code === 'ENOENT') return { outcome: 'unlisted-denied' };
      throw error;
    }
  }
  if (path === '/storage-quota-denied') {
    fs.writeFileSync('/storage/scratch/quota.txt', new Uint8Array(16));
    try {
      fs.appendFileSync('/storage/scratch/quota.txt', 'x');
    } catch (error) {
      if (error?.code === 'EDQUOT') return { outcome: 'quota-denied' };
      throw error;
    }
  }
  throw new Error(`storage evidence failed: ${path}`);
}

export default {
  async fetch(request) {
    const path = new URL(request.url).pathname;
    try {
      if (path === '/evidence/vfs-bundle') return json(bundleEvidence());
      if (path === '/evidence/vfs-tmp') return json(tmpEvidence());
      if (path === '/evidence/vfs-dev-null') return json(devNullEvidence());
      if (path === '/evidence/vfs-dev-zero') return json(devZeroEvidence());
      if (path === '/evidence/vfs-dev-random') return json(devRandomEvidence());
      if (path.startsWith('/storage-')) return json(storageEvidence(path));
      return json({ outcome: 'fail', error: 'unknown evidence route' }, 404);
    } catch (error) {
      return json({ outcome: 'fail', error: errorDetails(error) }, 500);
    }
  },
};
